INSERT INTO level
  (level_no, title, story, completion_story, question, correct_option_keys,
INSERT INTO level_option (level_id, option_key, label, sort_order) VALUES
  ((SELECT id FROM level WHERE level_no = 1), 'a', '{"zh-Hant":"借閱台（G/F）：負責圖書借還和預約書","zh-Hans":"借阅台（G/F）：负责图书借还和预约书","en":"Borrowing Desk (G/F): handles book loans and reserves"}', 1),
  ((SELECT id FROM level WHERE level_no = 1), 'b', '{"zh-Hant":"參考服務台（G/F）：解答任何關於使用圖書館的疑問，包括研究諮詢","zh-Hans":"参考服务台（G/F）：解答任何关于使用图书馆的疑问，包括研究咨询","en":"Reference Desk (G/F): answers queries about using the library, including research consultation"}', 2),
  ((SELECT id FROM level WHERE level_no = 1), 'c', '{"zh-Hant":"IT 櫃台（G/F）：解決系統與網路問題","zh-Hans":"IT 柜台（G/F）：解决系统与网路问题","en":"IT Service Desk (G/F): resolves system and network issues"}', 3),
  ((SELECT id FROM level WHERE level_no = 1), 'd', '{"zh-Hant":"多媒體櫃台（2/F）：提供多媒體設備和演播室服務","zh-Hans":"多媒体柜台（2/F）：提供多媒体设备和演播室服务","en":"Multimedia Desk (2/F): provides multimedia equipment and studio services"}', 4),
  ((SELECT id FROM level WHERE level_no = 2), 'a', '{"zh-Hant":"Chapter Two: Nicolas Iquan before 1627","zh-Hans":"Chapter Two: Nicolas Iquan before 1627","en":"Chapter Two: Nicolas Iquan before 1627"}', 1),
  ((SELECT id FROM level WHERE level_no = 2), 'b', '{"zh-Hant":"War, trade and piracy in the China seas (1622-1683)","zh-Hans":"War, trade and piracy in the China seas (1622-1683)","en":"War, trade and piracy in the China seas (1622-1683)"}', 2),
  ((SELECT id FROM level WHERE level_no = 2), 'c', '{"zh-Hant":"海上傭兵：十七世紀東亞海域的戰爭、貿易與海上劫掠","zh-Hans":"海上佣兵：十七世纪东亚海域的战争、贸易与海上劫掠","en":"海上傭兵：十七世紀東亞海域的戰爭、貿易與海上劫掠 (The Maritime Mercenaries)"}', 3),
  ((SELECT id FROM level WHERE level_no = 2), 'd', '{"zh-Hant":"海上冒險回憶錄：一位傭兵的日誌：1617-1627","zh-Hans":"海上冒险回忆录：一位佣兵的日志：1617-1627","en":"Memoirs of a Maritime Adventurer: A Mercenary''s Log, 1617-1627"}', 4),
  ((SELECT id FROM level WHERE level_no = 3), 'a', '{"zh-Hant":"2/F A 區：哲學、宗教、心理、教育及藝術區 (B, L-N)","zh-Hans":"2/F A 区：哲学、宗教、心理、教育及艺术区 (B, L-N)","en":"2/F Zone A: Philosophy, Religion, Psychology, Education & Arts (B, L-N)"}', 1),
  ((SELECT id FROM level WHERE level_no = 3), 'b', '{"zh-Hant":"2/F C 區：語言文學區 (P-PZ)","zh-Hans":"2/F C 区：语言文学区 (P-PZ)","en":"2/F Zone C: Language & Literature (P-PZ)"}', 2),
  ((SELECT id FROM level WHERE level_no = 3), 'c', '{"zh-Hant":"3/F A 區：科學及醫學區 (Q-V)","zh-Hans":"3/F A 区：科学及医学区 (Q-V)","en":"3/F Zone A: Science & Medicine (Q-V)"}', 3),
  ((SELECT id FROM level WHERE level_no = 3), 'd', '{"zh-Hant":"3/F C 區：歷史及地理區 (C-G)","zh-Hans":"3/F C 区：历史及地理区 (C-G)","en":"3/F Zone C: History & Geography (C-G)"}', 4),
  ((SELECT id FROM level WHERE level_no = 3), 'e', '{"zh-Hant":"4/F A 區：工商管理區 (H-HG)","zh-Hans":"4/F A 区：工商管理区 (H-HG)","en":"4/F Zone A: Business Management (H-HG)"}', 5),
  ((SELECT id FROM level WHERE level_no = 3), 'f', '{"zh-Hant":"4/F C 區：法律及公共行政區 (HJ-HX, J-K)","zh-Hans":"4/F C 区：法律及公共行政区 (HJ-HX, J-K)","en":"4/F Zone C: Law & Public Administration (HJ-HX, J-K)"}', 6),
  ((SELECT id FROM level WHERE level_no = 4), 'a', '{"zh-Hant":"③ ④ ① ②","zh-Hans":"③ ④ ① ②","en":"③ ④ ① ②"}', 1),
  ((SELECT id FROM level WHERE level_no = 4), 'b', '{"zh-Hant":"② ③ ① ④","zh-Hans":"② ③ ① ④","en":"② ③ ① ④"}', 2),
