  ((SELECT id FROM level WHERE level_no = 5), 'a', '{"zh-Hant":"橫琴水域","zh-Hans":"横琴水域","en":"Hengqin waters (橫琴水域)"}', 1),
  ((SELECT id FROM level WHERE level_no = 5), 'b', '{"zh-Hant":"十字門水域","zh-Hans":"十字门水域","en":"Cross Gate waters (十字門水域)"}', 2),
  ((SELECT id FROM level WHERE level_no = 5), 'c', '{"zh-Hant":"十字門和橫琴水域","zh-Hans":"十字门和横琴水域","en":"Cross Gate and Hengqin waters (十字門和橫琴水域)"}', 3),
  ((SELECT id FROM level WHERE level_no = 5), 'd', '{"zh-Hant":"澳門半島、氹仔、路環、大橫琴、小橫琴、灣仔之間的水道","zh-Hans":"澳门半岛、氹仔、路环、大横琴、小横琴、湾仔之间的水道","en":"The waterways between Macau Peninsula, Taipa, Coloane, Greater Hengqin, Lesser Hengqin, and Wanzai"}', 4),
  ((SELECT id FROM level WHERE level_no = 6), 'a', '{"zh-Hant":"明清廣州對外交通的主要航道","zh-Hans":"明清广州对外交通的主要航道","en":"Ming-Qing Guangzhou''s Major External Transport Routes"}', 1),
  ((SELECT id FROM level WHERE level_no = 6), 'b', '{"zh-Hant":"明宋應昌《全海圖註·廣東沿海圖》研究","zh-Hans":"明宋应昌《全海图注·广东沿海图》研究","en":"A Study of Song Yingchang''s Quan Hai Tu Zhu: Guangdong Coastal Map"}', 2),
  ((SELECT id FROM level WHERE level_no = 6), 'c', '{"zh-Hant":"濠鏡澳與亞馬港：香山縣若干地名考——以明代《全海圖註》為中心","zh-Hans":"濠镜澳与亚马港：香山县若干地名考——以明代《全海图注》为中心","en":"Haojing''ao and Yamagang: A Study of Xiangshan County Place Names — Centered on the Ming Quan Hai Tu Zhu"}', 3),
  ((SELECT id FROM level WHERE level_no = 6), 'd', '{"zh-Hant":"明代至清初的十三行與十字門海上貿易——以屈大均1662年澳門之行為中心","zh-Hans":"明代至清初的十三行与十字门海上贸易——以屈大均1662年澳门之行为中心","en":"The Thirteen Hongs and Cross Gate Maritime Trade from Ming to Early Qing — Centered on Qu Dajun''s 1662 Journey to Macau"}', 4),
  ((SELECT id FROM level WHERE level_no = 7), 'a', '{"zh-Hant":"1樓 A2 澳大人文庫","zh-Hans":"1楼 A2 澳大人文库","en":"1/F A2 UM Scholars Collection (澳大人文庫)"}', 1),
  ((SELECT id FROM level WHERE level_no = 7), 'b', '{"zh-Hant":"5樓 C1 大尺寸圖書","zh-Hans":"5楼 C1 大尺寸图书","en":"5/F C1 Oversize Books (大尺寸圖書)"}', 2),
  ((SELECT id FROM level WHERE level_no = 7), 'c', '{"zh-Hant":"3樓 C2 史地類書籍","zh-Hans":"3楼 C2 史地类书籍","en":"3/F C2 History & Geography (史地類書籍)"}', 3),
  ((SELECT id FROM level WHERE level_no = 7), 'd', '{"zh-Hant":"1樓 A7 參考書","zh-Hans":"1楼 A7 参考书","en":"1/F A7 Reference (參考書)"}', 4),
  ((SELECT id FROM level WHERE level_no = 8), 'a', '{"zh-Hant":"百年浮沉：法國耶穌會傳教團在華活動研究 (1685-1785)","zh-Hans":"百年浮沉：法国耶稣会传教团在华活动研究 (1685-1785)","en":"A Century of Ebbs and Flows: A Study of the French Jesuit Mission in China (1685-1785)（百年浮沉 : 法國耶穌會傳教團在華活動研究 (1685-1785)）"}', 1),
  ((SELECT id FROM level WHERE level_no = 8), 'b', '{"zh-Hant":"轉型時期澳葡政府財政的演變和發展 (1844-1888)","zh-Hans":"转型时期澳葡政府财政的演变和发展 (1844-1888)","en":"The Evolution and Development of Macau Portuguese Government Finances in Transition (1844-1888)（轉型時期澳葡政府財政的演變和發展 (1844-1888)）"}', 2),
  ((SELECT id FROM level WHERE level_no = 8), 'c', '{"zh-Hant":"Memoria sobre o estabelecimento de Macau escrita pelo Visconde de Santaré","zh-Hans":"Memoria sobre o estabelecimento de Macau escrita pelo Visconde de Santaré","en":"Memoria sobre o estabelecimento de Macau escrita pelo Visconde de Santaré"}', 3),
  ((SELECT id FROM level WHERE level_no = 8), 'd', '{"zh-Hant":"Relação da Embaixada e do que por respeito dela sucedeu que El Rei Nosso Senhor D. João o 5º no ano de 1725 mandou ao Imperador da Tartária e China, cujo reinado era Yum Chim","zh-Hans":"Relação da Embaixada e do que por respeito dela sucedeu que El Rei Nosso Senhor D. João o 5º no ano de 1725 mandou ao Imperador da Tartária e China, cujo reinado era Yum Chim","en":"Relação da Embaixada e do que por respeito dela sucedeu que El Rei Nosso Senhor D. João o 5º no ano de 1725 mandou ao Imperador da Tartária e China, cujo reinado era Yum Chim"}', 4),
  ((SELECT id FROM level WHERE level_no = 9), 'a', '{"zh-Hant":"The elements of geometrie of the most auncient philosopher Euclide of Megara.","zh-Hans":"The elements of geometrie of the most auncient philosopher Euclide of Megara.","en":"The elements of geometrie of the most auncient philosopher Euclide of Megara."}', 1),
  ((SELECT id FROM level WHERE level_no = 9), 'b', '{"zh-Hant":"Preclarissimus liber elementorum Euclidis perspicacissimi in artem geometrie incipit qua[m]foelicissime","zh-Hans":"Preclarissimus liber elementorum Euclidis perspicacissimi in artem geometrie incipit qua[m]foelicissime","en":"Preclarissimus liber elementorum Euclidis perspicacissimi in artem geometrie incipit qua[m]foelicissime"}', 2),
  ((SELECT id FROM level WHERE level_no = 9), 'c', '{"zh-Hant":"Euclidis Elementorum libri XV. breviter demonstrati.","zh-Hans":"Euclidis Elementorum libri XV. breviter demonstrati.","en":"Euclidis Elementorum libri XV. breviter demonstrati."}', 3),
  ((SELECT id FROM level WHERE level_no = 9), 'd', '{"zh-Hant":"Preclarissimus liber elementorum Euclidis","zh-Hans":"Preclarissimus liber elementorum Euclidis","en":"Preclarissimus liber elementorum Euclidis"}', 4),
  ((SELECT id FROM level WHERE level_no = 10), 'a', '{"zh-Hant":"保持安靜","zh-Hans":"保持安静","en":"Keep quiet"}', 1),
  ((SELECT id FROM level WHERE level_no = 10), 'b', '{"zh-Hant":"教科書僅供在 G028 內閱覽，不能帶出該房間","zh-Hans":"教科书仅供在 G028 内阅览，不能带出该房间","en":"Textbooks may only be used inside G028 and cannot be taken out"}', 2),
  ((SELECT id FROM level WHERE level_no = 10), 'c', '{"zh-Hant":"座位遺留物品，離開座位超過30分鐘，視為佔位（霸位）","zh-Hans":"座位遗留物品，离开座位超过30分钟，视为占位（霸位）","en":"Seats left unattended for over 30 minutes are considered occupied (seat hogging)"}', 3),
  ((SELECT id FROM level WHERE level_no = 10), 'd', '{"zh-Hant":"只要不影響其他讀者，可以在圖書館小睡","zh-Hans":"只要不影响其他读者，可以在图书馆小睡","en":"As long as it doesn''t disturb others, napping in the library is allowed"}', 4),
  ((SELECT id FROM level WHERE level_no = 10), 'e', '{"zh-Hant":"圖書館內飲食注意：飲料應有蓋，食物應無氣味和殘渣","zh-Hans":"图书馆内饮食注意：饮料应有盖，食物应无气味和残渣","en":"Drinks must have lids; food must be odorless and crumb-free"}', 5),
  ((SELECT id FROM level WHERE level_no = 10), 'f', '{"zh-Hant":"可以掃描所需的教科書章節，但需注意版權保護，不可超過全書的15%","zh-Hans":"可以扫描所需的教科书章节，但需注意版权保护，不可超过全书的15%","en":"You may scan textbook chapters, but must respect copyright — no more than 15% of the entire book"}', 6),
  ((SELECT id FROM level WHERE level_no = 11), 'a', '{"zh-Hant":"Location 標註 [LIB USE ONLY] 的書只能在館內閱讀，一般不能外借","zh-Hans":"Location 标注 [LIB USE ONLY] 的书只能在馆内阅读，一般不能外借","en":"Items marked [LIB USE ONLY] may only be read inside the library and generally cannot be borrowed"}', 1),
  ((SELECT id FROM level WHERE level_no = 11), 'b', '{"zh-Hant":"手機借書需在手機安裝 UM App，並登入自己的大學賬號","zh-Hans":"手机借书需在手机安装 UM App，并登录自己的大学账号","en":"Mobile borrowing requires installing the UM App and logging in with your university account"}', 2),
  ((SELECT id FROM level WHERE level_no = 11), 'c', '{"zh-Hant":"借書需要掃描圖書封底的 ISBN","zh-Hans":"借书需要扫描图书封底的 ISBN","en":"Borrowing requires scanning the ISBN on the back cover"}', 3),
  ((SELECT id FROM level WHERE level_no = 11), 'd', '{"zh-Hant":"借書需要掃描圖書封底內頁的條碼號（Barcode）","zh-Hans":"借书需要扫描图书封底内页的条码号（Barcode）","en":"Borrowing requires scanning the barcode on the inside back cover"}', 4),
  ((SELECT id FROM level WHERE level_no = 11), 'e', '{"zh-Hant":"成功完成借書後，才可以攜帶被借出的圖書離開圖書館","zh-Hans":"成功完成借书后，才可以携带被借出的图书离开图书馆","en":"You may only take books out of the library after successfully completing the borrowing process"}', 5),
  ((SELECT id FROM level WHERE level_no = 11), 'f', '{"zh-Hant":"如果離開圖書館時遇到警報聲響，請在「我的借書」裡檢查攜帶的圖書是否已成功借出","zh-Hans":"如果离开图书馆时遇到警报声响，请在「我的借书」里检查携带的图书是否已成功借出","en":"If the alarm sounds when leaving the library, check ''My Loans'' to verify the book was successfully borrowed"}', 6),
  ((SELECT id FROM level WHERE level_no = 12), 'a', '{"zh-Hant":"AI 使知識隨手可得，提供的答案條理清晰，不存在虛構或偏見","zh-Hans":"AI 使知识随手可得，提供的答案条理清晰，不存在虚构或偏见","en":"AI makes knowledge accessible and provides well-structured answers free from fabrication or bias"}', 1),
  ((SELECT id FROM level WHERE level_no = 12), 'b', '{"zh-Hant":"AI 的大語言模型都是用可靠語料訓練的，本身就是權威來源","zh-Hans":"AI 的大语言模型都是用可靠语料训练的，本身就是权威来源","en":"AI large language models are trained on reliable corpora and are themselves authoritative sources"}', 2),
  ((SELECT id FROM level WHERE level_no = 12), 'c', '{"zh-Hant":"大學圖書館提供的學術文獻經過了同行評審（Peer-reviewed），比通用 AI 工具找到的資料更可靠，因此可以不加質疑地引用","zh-Hans":"大学图书馆提供的学术文献经过了同行评审（Peer-reviewed），比通用 AI 工具找到的资料更可靠，因此可以不加质疑地引用","en":"Academic literature provided by university libraries has been peer-reviewed and is more reliable than general AI tools, therefore it can be cited without question"}', 3),
  ((SELECT id FROM level WHERE level_no = 12), 'd', '{"zh-Hant":"大量深入地讀書可以建立內化的知識體系，從而讓人能提出高質量的問題，識別出 AI 答案中的錯誤","zh-Hans":"大量深入地读书可以建立内化的知识体系，从而让人能提出高质量的问题，识别出 AI 答案中的错误","en":"Reading extensively and deeply builds an internalized knowledge system, enabling one to ask high-quality questions and identify errors in AI-generated answers"}', 4)
INSERT INTO item (item_key, name, description, image_url) VALUES
  ('item-01', '{"zh-Hant":"《博尋》使用指南","zh-Hans":"《博寻》使用指南","en":"BoQuest User Guide"}', '{"zh-Hant":"通往圖書館資源寶庫的鑰匙——學會使用博尋，掌握知識的入口。","zh-Hans":"通往图书馆资源宝库的钥匙——学会使用博寻，掌握知识的入口。","en":"The key to the library''s treasure trove of resources — master BoQuest, and you hold the entrance to all knowledge."}', '/assets/boquest-guide.png'),
  ('item-01-note', '{"zh-Hant":"泛黃字條","zh-Hans":"泛黄字条","en":"Yellowed Note"}', '{"zh-Hant":"簽名 N. Iquan, 1634——一首明代古詩，一段隱藏四百年的寶藏線索。","zh-Hans":"签名 N. Iquan, 1634——一首明代古诗，一段隐藏四百年的宝藏线索。","en":"Signed N. Iquan, 1634 — a Ming dynasty poem, a 400-year-old treasure clue waiting to be unraveled."}', '/assets/note-yellowed.png'),
  ('item-02', '{"zh-Hant":"Nicolas Iquan 檔案","zh-Hans":"Nicolas Iquan 档案","en":"Nicolas Iquan Dossier"}', '{"zh-Hant":"N. Iquan 即 Nicolas Iquan——明末海上霸主鄭芝龍在澳門受洗時的教名，Iquan 正是其小名「一官」。","zh-Hans":"N. Iquan 即 Nicolas Iquan——明末海上霸主郑芝龙在澳门受洗时的教名，Iquan 正是其小名「一官」。","en":"N. Iquan is Nicolas Iquan — the baptized name of Zheng Zhilong, the Ming dynasty''s overlord of the seas. ''Iquan'' was his childhood nickname, meaning ''First Official.''"}', '/assets/iquan-dossier.png'),
  ('item-03', '{"zh-Hant":"密碼表","zh-Hans":"密码表","en":"Cipher Table"}', '{"zh-Hant":"索書號構成及其排序方法——圖書館的「定位密碼」，每一本書都有它獨一無二的坐標。","zh-Hans":"索书号构成及其排序方法——图书馆的「定位密码」，每一本书都有它独一无二的坐标。","en":"The structure of call numbers and their sorting rules — the library''s ''positioning cipher,'' giving every book its unique coordinate."}', '/assets/call-number-cipher.png'),
  ('item-04', '{"zh-Hant":"海事便簽","zh-Hans":"海事便签","en":"Maritime Memo"}', '{"zh-Hant":"記載福松丸於1634年沉沒於十字澳西石——「福松」原來是鄭芝龍為長子鄭成功打造的旗艦！","zh-Hans":"记载福松丸于1634年沉没于十字澳西石——「福松」原来是郑芝龙为长子郑成功打造的旗舰！","en":"Records that the Fushong-maru sank at the Western Rock of the Cross Gate in 1634 — ''Fushong'' was the flagship Zheng Zhilong built for his eldest son Zheng Chenggong!"}', '/assets/maritime-memo.png'),
  ('item-05', '{"zh-Hant":"沉船點範圍圖","zh-Hans":"沉船点范围图","en":"Wreck Site Sketch"}', '{"zh-Hant":"你親手在地圖上圈畫出的沉船點範圍——十字門水域，即澳門半島、氹仔、路環、大橫琴、小橫琴、灣仔之間的水道。","zh-Hans":"你亲手在地图上圈画出的沉船点范围——十字门水域，即澳门半岛、氹仔、路环、大横琴、小横琴、湾仔之间的水道。","en":"You''ve circled the wreck area on the map — the Cross Gate waters: the channels between Macau Peninsula, Taipa, Coloane, Greater Hengqin, Lesser Hengqin, and Wanzai."}', '/assets/wreck-site-map.png'),
  ('item-06', '{"zh-Hant":"地名考證報告","zh-Hans":"地名考证报告","en":"Toponym Research Report"}', '{"zh-Hant":"考證出「西石」的大致地點——要精確定位，還需要親眼看到明代古地圖《全海圖註》。","zh-Hans":"考证出「西石」的大致地点——要精确定位，还需要亲眼看到明代古地图《全海图注》。","en":"Identifies the approximate location of ''Western Rock'' — but pinpointing it precisely requires seeing the Ming-era map ''Quan Hai Tu Zhu'' in person."}', '/assets/toponym-report.png'),
  ('item-07', '{"zh-Hant":"神秘的銀幣","zh-Hans":"神秘的银币","en":"Mysterious Silver Coin"}', '{"zh-Hant":"幣面上用細針刻著一行小字：「1/F C1：Metello」——這是一條指向下一站的路標。","zh-Hans":"币面上用细针刻著一行小字：「1/F C1：Metello」——这是一条指向下一站的路标。","en":"Etched on the coin in fine needlework is a line: ''1/F C1: Metello'' — a signpost pointing to the next stop."}', '/assets/silver-coin.png'),
  ('item-08', '{"zh-Hant":"「仁」字卡牌","zh-Hans":"「仁」字卡牌","en":"Card of ''Ren'' (仁 — Benevolence)"}', '{"zh-Hant":"Gin 仁 — amor seu caritas（愛與仁慈）。卡背寫著：''……福松……重啟天國之鑰，唯有眾人各司其職、彼此成就，方能守護……''","zh-Hans":"Gin 仁 — amor seu caritas（爱与仁慈）。卡背写著：''……福松……重启天国之钥，唯有众人各司其职、彼此成就，方能守护……''","en":"Gin 仁 — amor seu caritas (love and charity). The card''s reverse reads: ''...Fushong... to reopen the key of heaven, only when all fulfill their roles and elevate one another can it be safeguarded...''"}', '/assets/card-ren.png'),
  ('item-09', '{"zh-Hant":"「義」字卡牌","zh-Hans":"「义」字卡牌","en":"Card of ''Yi'' (義 — Righteousness)"}', '{"zh-Hant":"gni 義 — gratitudo（感恩與正義）。代表對知識傳播的使命感，象徵保護古籍、尊重知識。","zh-Hans":"gni 义 — gratitudo（感恩与正义）。代表对知识传播的使命感，象征保护古籍、尊重知识。","en":"gni 義 — gratitudo (gratitude and justice). Represents a sense of mission in spreading knowledge, symbolizing the protection of ancient texts and respect for learning."}', '/assets/card-yi.png'),
  ('item-10', '{"zh-Hant":"「禮」字卡牌","zh-Hans":"「礼」字卡牌","en":"Card of ''Li'' (禮 — Ritual/Propriety)"}', '{"zh-Hant":"Li 禮 — humanitas（人道）。羅明堅註釋：''此乃社群共處之基石。''四百年前的傳教士，將儒家的「禮」與西方的「人道主義」連結為文明對話的根基。","zh-Hans":"Li 礼 — humanitas（人道）。罗明坚注释：''此乃社群共处之基石。''四百年前的传教士，将儒家的「礼」与西方的「人道主义」连结为文明对话的根基。","en":"Li 禮 — humanitas (humaneness). Ruggieri annotated: ''This is the cornerstone of communal coexistence.'' Four centuries ago, this missionary linked the Confucian ''Li'' with Western ''humanitas'' as the foundation for civilizational dialogue."}', '/assets/card-li.png'),
  ('item-11', '{"zh-Hant":"「知」字卡牌","zh-Hans":"「知」字卡牌","en":"Card of ''Zhi'' (知 — Knowledge/Wisdom)"}', '{"zh-Hant":"ci 智 — Prudentia（審慎與智慧）。羅明堅寫道：''善用工具者，方能洞察未知。善用圖書館資源與服務，可以事半功倍。''","zh-Hans":"ci 智 — Prudentia（审慎与智慧）。罗明坚写道：''善用工具者，方能洞察未知。善用图书馆资源与服务，可以事半功倍。''","en":"ci 智 — Prudentia (prudence and wisdom). Ruggieri wrote: ''Those who master their tools can perceive the unknown. Those who master library resources and services achieve twice the result with half the effort.''"}', '/assets/card-zhi.png'),
  ('item-12', '{"zh-Hant":"「信」字卡牌","zh-Hans":"「信」字卡牌","en":"Card of ''Xin'' (信 — Integrity/Trust)"}', '{"zh-Hant":"Sin 信 — Veritas（真理）。象徵學術誠信、正確使用 AI、規範引用——所有知識能否成立的最終保證。","zh-Hans":"Sin 信 — Veritas（真理）。象征学术诚信、正确使用 AI、规范引用——所有知识能否成立的最终保证。","en":"Sin 信 — Veritas (truth). Symbolizes academic integrity, proper use of AI, and correct citation — the ultimate guarantor of whether knowledge can truly stand."}', '/assets/card-xin.png')
