SET NAMES utf8mb4;

   qr_answer, qr_location, qr_location_note, video_url, story_image_url,
   story_image_alt, story_image_caption)
VALUES
  (1, '{"zh-Hant":"第一關：初臨密境——尋找智慧的守門人","zh-Hans":"第一关：初临密境——寻找智慧的守门人","en":"Level 1: The Mysterious Note — Seek the Gatekeeper of Wisdom"}', '{"zh-Hant":"2026年8月，盛夏。你剛踏入澳門大學圖書館，在整理新生資料時，突然掉出一張泛黃的字條，紙面帶著若有若無的海鹽氣味，上面潦草地寫著幾行字：「濠雨風驟撼長宵，福松影沒十字澳。西石深藏無價寶，九章一開動皇朝。N. Iquan, 1634.」這是什麼？古詩？外文簽名？你決定找人問問。抬起頭，你看到圖書館大堂的標語——「有問題，問館員」。","zh-Hans":"2026年8月，盛夏。你刚踏入澳门大学图书馆，在整理新生资料时，突然掉出一张泛黄的字条，纸面带著若有若无的海盐气味，上面潦草地写著几行字：「濠雨风骤撼长宵，福松影没十字澳。西石深藏无价宝，九章一开动皇朝。N. Iquan, 1634.」这是什么？古诗？外文签名？你决定找人问问。抬起头，你看到图书馆大堂的标语——「有问题，问馆员」。","en":"August 2026, midsummer. You have just stepped into the University of Macau Library. While sorting through your orientation materials, a yellowed, worn note flutters out, carrying a faint trace of sea salt. Scribbled on it are a few lines: \\"Tempest rains lash the long night, Fushong vanishes at the Cross Gate. Western Rock hides a priceless treasure, Nine Chapters once opened will move the empire. N. Iquan, 1634.\\" What is this? An ancient poem? A foreign signature? You look up and see the library lobby''s motto: \\"Got questions? Ask a librarian.\\""}', '{"zh-Hant":"館員看了一眼字條，神色微動，壓低聲音告訴你：從2014年遷入新館開始，澳大的新生就會莫名其妙地收到這樣的紙條。傳說，這張紙條關係到一批價值連城的寶藏，只有能破解它的人才能得到——可惜至今無人成功。你還想追問，館員卻搖搖頭，不再多言，只遞給你一張折頁。「想破解這位Iquan的身分，先學會用『博尋』吧。」","zh-Hans":"馆员看了一眼字条，神色微动，压低声音告诉你：从2014年迁入新馆开始，澳大的新生就会莫名其妙地收到这样的纸条。传说，这张纸条关系到一批价值连城的宝藏，只有能破解它的人才能得到——可惜至今无人成功。你还想追问，馆员却摇摇头，不再多言，只递给你一张折页。「想破解这位Iquan的身份，先学会用『博寻』吧。」","en":"The librarian glances at the note, expression flickering. Lowering his voice, he tells you: ever since the library moved to its new building in 2014, UM freshmen have mysteriously received notes like this. Legend says the note points to a priceless treasure — but no one has ever cracked it. Before you can press further, he shakes his head and hands you a folded guide. \\"If you want to uncover who Iquan is, first learn to use BoQuest.\\""}', '{"zh-Hant":"你撿到一張神祕字條，既涉及歷史人物，又需要檢索資料。你該向圖書館哪個櫃檯求助？","zh-Hans":"你捡到一张神秘字条，既涉及历史人物，又需要检索资料。你该向图书馆哪个柜台求助？","en":"You''ve found a mysterious note involving historical figures and needing research. Which library service desk should you approach?"}', '["b"]', 'IQUAN1634', '{"zh-Hant":"G/F 圖書館大堂","zh-Hans":"G/F 图书馆大堂","en":"G/F Lobby · Reference Desk"}', '{"zh-Hant":"認識圖書館各服務櫃台功能，學會向參考館員求助","zh-Hans":"认识图书馆各服务柜台功能，学会向参考馆员求助","en":"Learn about library service desks and how to ask reference librarians for help"}', '/video/level1.mp4?v=20250710', NULL, NULL, NULL),
  (2, '{"zh-Hant":"第二關：神龍現身——知識深海的博尋","zh-Hans":"第二关：神龙现身——知识深海的博寻","en":"Level 2: The Dragon Emerges — BoQuest into the Deep Sea of Knowledge"}', '{"zh-Hant":"想破解這位iquan的身分，先學會用『博尋』吧。你來到資訊共享空間，打開一台電腦，向那個神祕簽名發起第一次檢索。","zh-Hans":"想破解这位iquan的身份，先学会用『博寻』吧。你来到资讯共享空间，打开一台电脑，向那个神秘签名发起第一次检索。","en":"\\"If you want to uncover who iquan is, first learn to use BoQuest.\\" You head to the Information Commons, open a computer, and launch your first search against that enigmatic signature."}', '{"zh-Hant":"檢索結果出來了——N. Iquan 就是 Nicolas Iquan，明末海上霸主鄭芝龍在澳門受洗時的教名，而「Iquan」正是他的小名「一官」。一個受洗的天主教徒、一個縱橫東亞的海上梟雄，他與這批寶藏究竟有何關係？你迫切想讀到這本書的細節。可它在哪一層書架上？","zh-Hans":"检索结果出来了——N. Iquan 就是 Nicolas Iquan，明末海上霸主郑芝龙在澳门受洗时的教名，而「Iquan」正是他的小名「一官」。一个受洗的天主教徒、一个纵横东亚的海上枭雄，他与这批宝藏究竟有何关系？你迫切想读到这本书的细节。可它在哪一层书架上？","en":"The search results are in — N. Iquan is Nicolas Iquan, the baptized name Zheng Zhilong received in Macau. \\"Iquan\\" was his childhood nickname, \\"Yiguan\\" (First Official). A baptized Catholic, a maritime warlord who dominated East Asian waters — what does he have to do with this treasure? You''re desperate to read the book. But which floor is it on?"}', '{"zh-Hant":"在圖書館主頁的博尋搜索框中輸入「Iquan」，能夠揭開這個神秘人身份的圖書是？（提示：(1) 用界面篩選（Filter）功能將資源類型限定為「圖書（Books）」，排除圖書章節和論文；(2) 查看找到的圖書描述（Description）資訊，注意中英文其實是同一本書。","zh-Hans":"在图书馆主页的博寻搜索框中输入「Iquan」，能够揭开这个神秘人身份的图书是？（提示：(1) 用界面筛选（Filter）功能将资源类型限定为「图书（Books）」，排除图书章节和论文；(2) 查看找到的图书描述（Description）资讯，注意中英文其实是同一本书。","en":"Type ''Iquan'' into the library''s BoQuest search. Which books reveal this mysterious person''s identity? (Hint: use filters to limit Resource Type to ''Books'' — note that the Chinese and English results are the same book.)"}', '["b","c"]', 'BOQUESTFS', '{"zh-Hant":"G/F 資訊共享空間","zh-Hans":"G/F 资讯共享空间","en":"G/F Information Commons"}', '{"zh-Hant":"學習使用博尋（BoQuest）發現系統，掌握篩選功能與館藏檢索","zh-Hans":"学习使用博寻（BoQuest）发现系统，掌握筛选功能与馆藏检索","en":"Learn to use BoQuest discovery system, master filters and catalog search"}', NULL, NULL, NULL, NULL),
  (3, '{"zh-Hant":"第三關：座標解讀——書海中的主題分區","zh-Hans":"第三关：座标解读——书海中的主题分区","en":"Level 3: Decoding the Map — Subject Zones in the Sea of Books"}', '{"zh-Hant":"為了找到鄭芝龍的相關資訊，你迫切想知道War, trade and piracy in the China seas (1622-1683)中的內容，裡面會有寶藏的下落嗎？可它藏在哪一層書架上？你得先在這座如迷宮般的圖書館裡，找到它所屬的主題領地。","zh-Hans":"为了找到郑芝龙的相关资讯，你迫切想知道War, trade and piracy in the China seas (1622-1683)中的内容，里面会有宝藏的下落吗？可它藏在哪一层书架上？你得先在这座如迷宫般的图书馆里，找到它所属的主题领地。","en":"Eager to learn more about Zheng Zhilong, you''re desperate to read War, Trade and Piracy in the China Seas (1622–1683). Could the treasure''s location be hidden within its pages? But where is it among the library''s maze of shelves? First, you must find which subject territory it belongs to."}', '{"zh-Hant":"確定了！這本書屬於歷史與地理區，在三樓 C 區。但同一區書架綿延數十米，這本書究竟卡在哪一格？你低頭看了看手中剛拿到的密碼表，意識到真正的「定位密碼」是那串索書號。","zh-Hans":"确定了！这本书属于历史与地理区，在三楼 C 区。但同一区书架绵延数十米，这本书究竟卡在哪一格？你低头看了看手中刚拿到的密码表，意识到真正的「定位密码」是那串索书号。","en":"Confirmed — History & Geography, 3/F Zone C. But the shelves stretch for dozens of meters. Where exactly is this book? You look down at the cipher table in your hands and realize the true \\"positioning code\\" is that string of call numbers."}', '{"zh-Hant":"根據學科主題，這本《War, trade and piracy in the China seas》應該存放在哪個區域？（提示：該書記錄了古代東亞海域的故事）","zh-Hans":"根据学科主题，这本《War, trade and piracy in the China seas》应该存放在哪个区域？（提示：该书记录了古代东亚海域的故事）","en":"Based on its subject, where should ''War, trade and piracy in the China seas'' be shelved? (Hint: the book chronicles tales of ancient East Asian seas)"}', '["d"]', 'DS7532CHE', '{"zh-Hant":"3/F A 區·主題區介紹海報旁","zh-Hans":"3/F A 区·主题区介绍海报旁","en":"3/F Zone A · Near Subject Zone Guide Poster"}', '{"zh-Hant":"認識圖書館學科主題分區，理解館藏組織邏輯","zh-Hans":"认识图书馆学科主题分区，理解馆藏组织逻辑","en":"Learn the library''s subject zone organization and collection layout logic"}', NULL, NULL, NULL, NULL),
  (4, '{"zh-Hant":"第四關：密文擷取——索書號的排序邏輯","zh-Hans":"第四关：密文撷取——索书号的排序逻辑","en":"Level 4: Cipher Extraction — The Logic of Call Numbers"}', '{"zh-Hant":"你繼續尋找圖書，心想書中一定會有寶藏的下落，另外「濠雨風驟撼長宵，福松影沒十字澳。西石深藏無價寶，九章一開動皇朝。」又是什麼意思？福松是誰？難道是他藏起了寶藏嗎？你來到三樓歷史與地理區，但這本書究竟在哪一格？博尋提供了它的索書號：【DS 753.2 Che 2013】。最終你在無數書脊中找到了「那一本」","zh-Hans":"你继续寻找图书，心想书中一定会有宝藏的下落，另外「濠雨风骤撼长宵，福松影没十字澳。西石深藏无价宝，九章一开动皇朝。」又是什么意思？福松是谁？难道是他藏起了宝藏吗？你来到三楼历史与地理区，但这本书究竟在哪一格？博寻提供了它的索书号：【DS 753.2 Che 2013】。最终你在无数书脊中找到了「那一本」","en":"You continue searching, convinced the book holds clues to the treasure. And what does the poem mean — \\"Tempest rains lash the long night, Fushong vanishes at the Cross Gate...\\"? Who is Fushong? Could he have hidden the treasure? You head to 3/F History & Geography. But where exactly is this book? BoQuest gives its call number: DS 753.2 Che 2013. Among countless spines, you finally pull out the one."}', '{"zh-Hant":"你終於抽出了這本書。翻動書頁時，一張夾藏其中的紙條飄落，上面潦草地寫著：「明崇禎七年，長子福松十歲慶生。一官造船福松丸。」你恍然大悟——「福松」原來不是人，而是一艘船！是鄭芝龍為長子鄭成功（小名福松）打造的旗艦「福松丸」！崇禎七年正是字條上的1634年。就在福松丸下水那年，這艘船遭遇風暴、觸礁沉沒，船上無價之寶從此不知所蹤。「十字澳」與「西石」——正是寶藏的藏身之處！","zh-Hans":"你终于抽出了这本书。翻动书页时，一张夹藏其中的纸条飘落，上面潦草地写著：「明崇祯七年，长子福松十岁庆生。一官造船福松丸。」你恍然大悟——「福松」原来不是人，而是一艘船！是郑芝龙为长子郑成功（小名福松）打造的旗舰「福松丸」！崇祯七年正是字条上的1634年。就在福松丸下水那年，这艘船遭遇风暴、触礁沉没，船上无价之宝从此不知所踪。「十字澳」与「西石」——正是宝藏的藏身之处！","en":"You finally pull out the book. As you turn the pages, a slip of paper flutters down: \\"The 7th year of Chongzhen, the eldest son Fushong turns ten. Yiguan builds the ship Fushong-maru.\\" It hits you — \\"Fushong\\" was not a person but a ship! The flagship Zheng Zhilong built for his son Zheng Chenggong! 1634, the very year on the note — the Fushong-maru struck a reef in a storm and sank. Its priceless cargo was lost without a trace. \\"Cross Gate\\" and \\"Western Rock\\" — these mark the treasure''s resting place!"}', '{"zh-Hant":"以下是4本書的索書號：① DS 753.2 Che 2013　② DP 756 Seq 1982　③ DS 79 Shi 1996　④ DS 753.2 Bro 2023。請問書架上由左至右正確的前後順序是？（提示：類目號按A-Z排序，細類號按整體數字大小排序，作者代碼逐位A-Z排序，同年份按出版年先後）","zh-Hans":"以下是4本书的索书号：① DS 753.2 Che 2013　② DP 756 Seq 1982　③ DS 79 Shi 1996　④ DS 753.2 Bro 2023。请问书架上由左至右正确的前后顺序是？（提示：类目号按A-Z排序，细类号按整体数字大小排序，作者代码逐位A-Z排序，同年份按出版年先后）","en":"Here are 4 call numbers: ① DS 753.2 Che 2013  ② DP 756 Seq 1982  ③ DS 79 Shi 1996  ④ DS 753.2 Bro 2023. What is the correct left-to-right order on the shelf? (Hint: class letters sort A–Z, class numbers as whole decimals, author codes letter-by-letter A–Z, then by publication year.)"}', '["d"]', 'FUSHONGMR', '{"zh-Hant":"3/F C 區書架","zh-Hans":"3/F C 区书架","en":"3/F Zone C · Bookshelves"}', '{"zh-Hant":"掌握索書號排序規則，學會在書架上快速定位圖書","zh-Hans":"掌握索书号排序规则，学会在书架上快速定位图书","en":"Master call number sorting rules to quickly locate books on shelves"}', '/video/level4-fushong.mp4?v=20250710', NULL, NULL, NULL),
  (5, '{"zh-Hant":"第五關：時空重疊——AI 賦能的數字航圖","zh-Hans":"第五关：时空重叠——AI 赋能的数字航图","en":"Level 5: Time-Space Overlay — AI-Powered Digital Charting"}', '{"zh-Hant":"「十字澳」與「西石」——正是寶藏的藏身之處！你試著用博尋查詢這些明代舊地名，卻一無所獲。這時你注意到搜索框旁的「AI 賦能博尋」按鈕——試試 AI 吧。","zh-Hans":"「十字澳」与「西石」——正是宝藏的藏身之处！你试著用博寻查询这些明代旧地名，却一无所获。这时你注意到搜索框旁的「AI 赋能博寻」按钮——试试 AI 吧。","en":"\\"Cross Gate\\" and \\"Western Rock\\" — these mark the treasure''s resting place! But searching these Ming-era place names in BoQuest yields nothing. Then you notice a button beside the search bar: \\"AI Enhanced BoQuest.\\" Time to try AI."}', '{"zh-Hant":"原來「十字澳」就是十字門水域——澳門半島、氹仔、路環、大橫琴、小橫琴、灣仔之間的水道。但這個範圍還是太大，看來關鍵仍在「西石」。AI 給出的答案列出了來源，其中一篇文章引起了你的注意——《珠澳十字門水域船舶擱淺成因及對策》。","zh-Hans":"原来「十字澳」就是十字门水域——澳门半岛、氹仔、路环、大横琴、小横琴、湾仔之间的水道。但这个范围还是太大，看来关键仍在「西石」。AI 给出的答案列出了来源，其中一篇文章引起了你的注意——《珠澳十字门水域船舶搁浅成因及对策》。","en":"The \\"Cross Gate\\" (十字澳) is the Cross Gate waters — the channels between Macau Peninsula, Taipa, Coloane, Greater Hengqin, Lesser Hengqin, and Wanzai. But that''s still too large an area. The key must be \\"Western Rock.\\" The AI''s answer lists its sources — one article catches your eye: \\"Causes and Countermeasures of Ship Groundings in the Zhuhai-Macau Cross Gate Waters.\\""}', '{"zh-Hant":"十字澳在哪裡呢？請根據 AI 賦能博尋給出的答案選擇正確的表述：","zh-Hans":"十字澳在哪里呢？请根据 AI 赋能博寻给出的答案选择正确的表述：","en":"What is the location of Shi Zi Men (Cross Gate) in Macao (十字澳)? Based on the AI Enhanced BoQuest results, select the correct descriptions:"}', '["b","d"]', 'CRUZGATE', '{"zh-Hant":"4/F A 區·查詢電腦（靠近電梯 ）","zh-Hans":"4/F A 区·查询电脑（靠近电梯 ）","en":"4/F Zone A · Search Computers (near the elevator)"}', '{"zh-Hant":"認識 AI 賦能博尋功能，學會使用 UMPass 登入並驗證 AI 答案來源","zh-Hans":"认识 AI 赋能博寻功能，学会使用 UMPass 登录并验证 AI 答案来源","en":"Discover AI Enhanced BoQuest, learn to log in with UMPass and verify AI-generated sources"}', NULL, NULL, NULL, NULL),
  (6, '{"zh-Hant":"第六關：文獻考古——資料庫的深潛","zh-Hans":"第六关：文献考古——资料库的深潜","en":"Level 6: Archaeological Dig — Deep Diving into Databases"}', '{"zh-Hant":"AI 給出的答案列出了來源，其中一篇文章引起你的注意——《珠澳十字門水域船舶擱淺成因及對策》。你點開連結，從「Full text availability」進入中國學術期刊全文資料庫（CNKI），順利讀到了全文。然而通篇讀下來，並沒有「西石」。看來「西石」是明代舊稱，如今或許改了名字。你決定在 CNKI 中以主題「十字門」檢索，用學科「中國古代史」篩選，追尋「西石」的真正位置。","zh-Hans":"AI 给出的答案列出了来源，其中一篇文章引起你的注意——《珠澳十字门水域船舶搁浅成因及对策》。你点开连结，从「Full text availability」进入中国学术期刊全文资料库（CNKI），顺利读到了全文。然而通篇读下来，并没有「西石」。看来「西石」是明代旧称，如今或许改了名字。你决定在 CNKI 中以主题「十字门」检索，用学科「中国古代史」筛选，追寻「西石」的真正位置。","en":"The AI''s answer includes sources. One article catches your eye — ''Causes and Countermeasures of Ship Groundings in the Zhuhai-Macau Cross Gate Waters.'' You follow the link, select ''Full text availability'' → CNKI (China Academic Journals Full-text Database), and read the full article. But ''Western Rock'' is nowhere to be found. It must be a Ming-era name that has since changed. You decide to search CNKI with the subject ''Cross Gate'' (十字門), filtered by discipline ''Ancient Chinese History,'' to track down the true location of Western Rock."}', '{"zh-Hant":"找到了！《濠鏡澳與亞馬港：香山縣若干地名考——以明代〈全海圖註〉為中心》這篇文章考證出了「西石」的大致地點。但作者沒有附上他所依據的明代地圖《全海圖註》。要精確定位，你必須親眼看到那張古老的地圖。圖書館裡，會有這套珍稀古圖嗎？","zh-Hans":"找到了！《濠镜澳与亚马港：香山县若干地名考——以明代〈全海图注〉为中心》这篇文章考证出了「西石」的大致地点。但作者没有附上他所依据的明代地图《全海图注》。要精确定位，你必须亲眼看到那张古老的地图。图书馆里，会有这套珍稀古图吗？","en":"Found it! The article \\"Haojing''ao and Yamagang: A Study of Xiangshan County Place Names — Centered on the Ming Quan Hai Tu Zhu\\" identifies the approximate location of \\"Western Rock.\\" But the author didn''t include the Ming-era map Quan Hai Tu Zhu. To pinpoint the exact location, you must see that ancient map with your own eyes. Does the library hold this rare atlas?"}', '{"zh-Hant":"在 CNKI 中以主題「十字門」檢索、學科「中國古代史」篩選，以下哪一篇文章提到了「西石」？（提示：請在四篇文章的全文中，搜尋關鍵詞「西石」，並確認其是否為考證對象。）","zh-Hans":"在 CNKI 中以主题「十字门」检索、学科「中国古代史」筛选，以下哪一篇文章提到了「西石」？（提示：请在四篇文章的全文中，搜寻关键词「西石」，并确认其是否为考证对象。）","en":"Searching CNKI with subject ''Cross Gate'' (十字門) and filtering by ''Ancient Chinese History,'' which article mentions ''Western Rock'' (西石)? (Hint: search the full text of all four articles for the keyword ''西石'' and verify whether it is the subject of textual research.)"}', '["c"]', 'PEDRAMEIO', '{"zh-Hant":"1/F A 區·澳大人·文庫","zh-Hans":"1/F A 区·澳大人·文库","en":"1/F Zone A · UM Scholars Collection"}', '{"zh-Hant":"學習使用 CNKI 等中文學術資料庫，掌握學科篩選與文獻檢索技巧","zh-Hans":"学习使用 CNKI 等中文学术资料库，掌握学科筛选与文献检索技巧","en":"Learn to use CNKI and other Chinese academic databases, master discipline filtering and literature search"}', NULL, NULL, NULL, NULL),
  (7, '{"zh-Hant":"第七關：中西之橋——澳門的古老真容","zh-Hans":"第七关：中西之桥——澳门的古老真容","en":"Level 7: Bridge Between East and West — Macau''s Ancient Face"}', '{"zh-Hant":"通過博尋，你驚喜地查到圖書館藏有《全海圖註》，位置在 1/F B4。你點開索書號右側的「Locate」圖標，打開了對應樓層的 Floor Plan。在澳門坊，你找到了這套珍貴古圖。書中繪出了「西石」的位置，旁邊有人用鉛筆寫下一行小字：Pedra do Meio？正踟躇間，你注意到柱子上掛著一張澳門古地圖——就在大、小橫琴、氹仔和路環構成的下十字門西側，赫然標著「Pedra do Meio」。你讀了讀經緯度，心頭一震：這正是現在澳大圖書館的所在地！你激動地拍了一下地圖畫框，一枚銀幣從框後鬆動、掉了出來。","zh-Hans":"通过博寻，你惊喜地查到图书馆藏有《全海图注》，位置在 1/F B4。你点开索书号右侧的「Locate」图标，打开了对应楼层的 Floor Plan。在澳门坊，你找到了这套珍贵古图。书中绘出了「西石」的位置，旁边有人用铅笔写下一行小字：Pedra do Meio？正踟躇间，你注意到柱子上挂著一张澳门古地图——就在大、小横琴、氹仔和路环构成的下十字门西侧，赫然标著「Pedra do Meio」。你读了读经纬度，心头一震：这正是现在澳大图书馆的所在地！你激动地拍了一下地图画框，一枚银币从框后松动、掉了出来。","en":"Through BoQuest, you''re thrilled to discover the library holds Quan Hai Tu Zhu, located at 1/F B4. You click the ''Locate'' icon beside the call number and open the floor plan. In the Macau Corner, you find this precious ancient atlas. It marks ''Western Rock,'' and beside it, someone has penciled a small note: Pedra do Meio? While puzzling over this, you notice an old map of Macau hanging on a pillar — and there, west of the Lower Cross Gate formed by Greater and Lesser Hengqin, Taipa, and Coloane, is clearly marked ''Pedra do Meio.'' You read the coordinates and your heart pounds: this is exactly where the UM Library now stands! You excitedly tap the map frame, and a silver coin slips loose from behind it."}', '{"zh-Hant":"你撿起銀幣仔細端詳。幣面上用細針刻著一行小字：「1/F C1：Metello」。1/F C1 正是本校學位論文區——這是一條指向下一站的路標。既然寶藏就在圖書館腳下，必定有前人留下過線索。","zh-Hans":"你捡起银币仔细端详。币面上用细针刻著一行小字：「1/F C1：Metello」。1/F C1 正是本校学位论文区——这是一条指向下一站的路标。既然宝藏就在图书馆脚下，必定有前人留下过线索。","en":"You pick up the coin and examine it closely. Etched on its surface in fine needlework is a line: \\"1/F C1: Metello.\\" 1/F C1 is the UM Theses & Dissertations section — a signpost pointing to the next stop. If the treasure lies beneath the library, someone before you must have left clues."}', '{"zh-Hant":"這套標註為 1/F B4 的《全海圖註》，除了在澳門坊外，還存在於哪些專區？（提示：使用博尋，搜索書名，查看館藏位置）","zh-Hans":"这套标注为 1/F B4 的《全海图注》，除了在澳门坊外，还存在于哪些专区？（提示：使用博寻，搜索书名，查看馆藏位置）","en":"Marked as 1/F B4, besides the Macau Corner, where else can the Quan Hai Tu Zhu be found? (Hint: Use BoQuest, search the title, and check the holdings locations)"}', '["a","b"]', 'SILVER1643', '{"zh-Hant":"1/F 澳門坊","zh-Hans":"1/F 澳门坊","en":"1/F · Macau Corner"}', '{"zh-Hant":"認識澳門坊及特藏資源，學會使用 Locate 功能在樓層平面圖上定位","zh-Hans":"认识澳门坊及特藏资源，学会使用 Locate 功能在楼层平面图上定位","en":"Explore the Macau Corner and special collections, learn to use the Locate feature on floor plans"}', '/video/level7-coin.mp4?v=20250710', NULL, NULL, NULL),
  (8, '{"zh-Hant":"第八關：傳承之薪——校園裡的守望者","zh-Hans":"第八关：传承之薪——校园里的守望者","en":"Level 8: Torch of Legacy — The Campus Guardians"}', '{"zh-Hant":"銀幣上的「Metello」是什麼意思？1/F C1 正是本校學位論文區。既然寶藏就在圖書館腳下，必定有前人留下過線索——你決定查閱學長前輩們的研究精華。在 UM Dissertations & Theses Collection 平台以「Metello」查詢，你找到了一篇博士論文。","zh-Hans":"银币上的「Metello」是什么意思？1/F C1 正是本校学位论文区。既然宝藏就在图书馆脚下，必定有前人留下过线索——你决定查阅学长前辈们的研究精华。在 UM Dissertations & Theses Collection 平台以「Metello」查询，你找到了一篇博士论文。","en":"What does ''Metello'' on the coin mean? 1/F C1 is the UM Theses & Dissertations section. If the treasure lies beneath the library, someone before you must have left clues — you decide to search the research of past scholars. On the UM Dissertations & Theses Collection platform, you search ''Metello'' and find a doctoral thesis."}', '{"zh-Hant":"原來，1725年葡萄牙國王派使臣麥德樂來華覲見雍正皇帝，但麥德樂在澳門逗留近一年，實際上是為執行一項秘密任務——尋找隨福松丸沉沒的耶穌會寶物。你在論文夾層中發現一張便簽和一張「仁」字卡牌：卡面寫著\\"Gin 仁 — amor seu caritas\\"（愛與仁慈）；卡背還有兩行字：「……福松……重啟天國之鑰，唯有眾人各司其職、彼此成就，方能守護……」原來這批寶藏，從來不是一個人能獨力守護的。","zh-Hans":"原来，1725年葡萄牙国王派使臣麦德乐来华觐见雍正皇帝，但麦德乐在澳门逗留近一年，实际上是为执行一项秘密任务——寻找随福松丸沉没的耶稣会宝物。你在论文夹层中发现一张便签和一张「仁」字卡牌：卡面写著\\"Gin 仁 — amor seu caritas\\"（爱与仁慈）；卡背还有两行字：「……福松……重启天国之钥，唯有众人各司其职、彼此成就，方能守护……」原来这批宝藏，从来不是一个人能独力守护的。","en":"In 1725, the Portuguese king sent envoy Metello to the court of the Yongzheng Emperor. But Metello lingered in Macau for nearly a year — his real mission was to recover Jesuit treasures lost with the Fushong-maru. Hidden in the thesis binding, you find a note and a card marked \\"Ren\\" (仁): its face reads \\"Gin 仁 — amor seu caritas\\" (love and charity); its reverse says: \\"...Fushong... to reopen the key of heaven, only when all fulfill their roles and elevate one another can it be safeguarded...\\" This treasure was never meant to be guarded by one person alone."}', '{"zh-Hant":"你要找的是一篇提到「葡萄牙使臣麥德樂（Embaixada de Alexandre Metelo de Sousa e Meneses à China no ano de 1725）」的本校博士論文。它的題目是？","zh-Hans":"你要找的是一篇提到「葡萄牙使臣麦德乐（Embaixada de Alexandre Metelo de Sousa e Meneses à China no ano de 1725）」的本校博士论文。它的题目是？","en":"You''re looking for a UM doctoral thesis mentioning ''the Portuguese envoy Alexandre Metelo de Sousa e Meneses'' embassy to China in 1725.'' What is its title?"}', '["a"]', 'METELO1725', '{"zh-Hant":"1/F C1·本校學位論文區","zh-Hans":"1/F C1·本校学位论文区","en":"1/F C1 · UM Theses & Dissertations Section"}', '{"zh-Hant":"學習使用 UM Dissertations & Theses Collection 平台查找本校論文","zh-Hans":"学习使用 UM Dissertations & Theses Collection 平台查找本校论文","en":"Learn to use the UM Dissertations & Theses Collection platform to find UM theses and dissertations"}', NULL, NULL, NULL, NULL),
  (9, '{"zh-Hant":"第九關：鎮館之寶——中西交流的鑰匙","zh-Hans":"第九关：镇馆之宝——中西交流的钥匙","en":"Level 9: The Library''s Crown Jewels — Keys to East-West Exchange"}', '{"zh-Hant":"原來1725年葡萄牙國王派使臣麥德樂來華覲見雍正皇帝，實為執行秘密任務——尋找隨福松丸沉沒的耶穌會寶物。循著麥德樂的線索，你了解到澳大圖書館的鎮館之寶中，有一件正是麥德樂來華的報告手稿。報告中提到他發現了兩件寶物的線索：一件是「西方科學的基石」，一件是「東方智慧的寶藏」。他沒有寫明是什麼，只留下一串奇怪的文字——1491 Euclid。","zh-Hans":"原来1725年葡萄牙国王派使臣麦德乐来华觐见雍正皇帝，实为执行秘密任务——寻找随福松丸沉没的耶稣会宝物。循著麦德乐的线索，你了解到澳大图书馆的镇馆之宝中，有一件正是麦德乐来华的报告手稿。报告中提到他发现了两件宝物的线索：一件是「西方科学的基石」，一件是「东方智慧的宝藏」。他没有写明是什么，只留下一串奇怪的文字——1491 Euclid。","en":"In 1725, the Portuguese king sent envoy Metello to the court of the Yongzheng Emperor. But Metello lingered in Macau for nearly a year — his real mission was to recover Jesuit treasures lost with the Fushong-maru. Following Metello''s trail, you learn that among the UM Library''s crown jewels is the very manuscript of Metello''s embassy report. It mentions he found clues to two treasures: one ''cornerstone of Western science,'' one ''treasure of Eastern wisdom.'' He didn''t name them, leaving only a cryptic inscription — 1491 Euclid."}', '{"zh-Hant":"在特藏展區的玻璃櫃前，你看到了兩件珍貴古籍並列陳放：1491年威尼斯出版的歐幾里德《幾何原本》搖籃本，以及1584年羅明堅的手稿《仁義禮知信》。原來利瑪竇與徐光啟合譯《幾何原本》未竟，耶穌會決定將完整版送往中國；羅明堅的手稿則是要向天朝證明尊儒崇儒之心。兩件聖物隨福松丸北上，卻在1634年沉入西石。1726年麥德樂在西石尋回了手稿，讓聖物在四百年後成為澳大的鎮館之寶。你細讀展櫃說明牌，末尾引述麥德樂的話：「要在這片土地獲得真理，必須先學會他們的『禮』。」","zh-Hans":"在特藏展区的玻璃柜前，你看到了两件珍贵古籍并列陈放：1491年威尼斯出版的欧几里德《几何原本》摇篮本，以及1584年罗明坚的手稿《仁义礼知信》。原来利玛窦与徐光启合译《几何原本》未竟，耶稣会决定将完整版送往中国；罗明坚的手稿则是要向天朝证明尊儒崇儒之心。两件圣物随福松丸北上，却在1634年沉入西石。1726年麦德乐在西石寻回了手稿，让圣物在四百年后成为澳大的镇馆之宝。你细读展柜说明牌，末尾引述麦德乐的话：「要在这片土地获得真理，必须先学会他们的『礼』。」","en":"Before the glass display case, you see two precious ancient books: the 1491 Venice incunabulum of Euclid''s Elements, and Michele Ruggieri''s 1584 manuscript \\"Ren Yi Li Zhi Xin.\\" Ricci and Xu Guangqi had translated Euclid together, but Ricci died after completing only six volumes. The Jesuits decided to send the complete 1491 edition to China; Ruggieri''s manuscript would prove their respect for Confucian values. Both sacred items were aboard the Fushong-maru when it sank in 1634. Metello recovered the manuscript at Western Rock in 1726, allowing these treasures to become the crown jewels of the UM Library four centuries later. The display note quotes Metello: \\"To obtain truth in this land, one must first learn their Li.\\""}', '{"zh-Hant":"用 BoQuest 查找「1491 Euclid」，按年代排序最古老在前（Sort by: Date — oldest），位置含「Rare Book Room」的那本書名是？","zh-Hans":"用 BoQuest 查找「1491 Euclid」，按年代排序最古老在前（Sort by: Date — oldest），位置含「Rare Book Room」的那本书名是？","en":"Search BoQuest for ''1491 Euclid,'' sort by Date — oldest first. Which title''s location includes ''Rare Book Room''?"}', '["b"]', 'EUCLID1491', '{"zh-Hant":"1/F B1·古籍館（Rare Book Room）","zh-Hans":"1/F B1·古籍馆（Rare Book Room）","en":"1/F B1 · Rare Book Room"}', '{"zh-Hant":"認識圖書館古籍特藏，學會查看數字化古籍及使用 AI 翻譯輔助閱讀","zh-Hans":"认识图书馆古籍特藏，学会查看数字化古籍及使用 AI 翻译辅助阅读","en":"Discover the library''s rare book collection, learn to access digitized ancient texts and use AI translation"}', '/video/level9-treasure.mp4?v=20250710', NULL, NULL, NULL),
  (10, '{"zh-Hant":"第十關：克己復禮——秩序與空間的修行","zh-Hans":"第十关：克己复礼——秩序与空间的修行","en":"Level 10: Self-Restraint and Ritual — The Practice of Order and Space"}', '{"zh-Hant":"仁、義……這不正是「五常」嗎！你拿著「義」字卡循著「先學會他們的禮」的提示來到 G028——這裡存放著通往知識最基礎的工具：教科書。","zh-Hans":"仁、义……这不正是「五常」吗！你拿著「义」字卡循著「先学会他们的礼」的提示来到 G028——这里存放著通往知识最基础的工具：教科书。","en":"Ren, Yi... this must be the ''Five Constants''! Clutching the Yi card and following the hint — ''first learn their Li'' — you head to G028, home to the most fundamental tools of knowledge: textbooks."}', '{"zh-Hant":"你逐一核對圖書館禮儀規範，在教科書架的隱蔽處發現了「禮」字卡牌。卡背是羅明堅當年的註釋：「Li 禮：humanitas。此乃社群共處之基石。」你忽然讀懂了這位四百年前的傳教士——他巧妙地將儒家的「禮」與西方的「人道主義（humanitas）」連結起來，視之為文明對話的根基。","zh-Hans":"你逐一核对图书馆礼仪规范，在教科书架的隐蔽处发现了「礼」字卡牌。卡背是罗明坚当年的注释：「Li 礼：humanitas。此乃社群共处之基石。」你忽然读懂了这位四百年前的传教士——他巧妙地将儒家的「礼」与西方的「人道主义（humanitas）」连结起来，视之为文明对话的根基。","en":"Checking each etiquette rule one by one, you discover the \\"Li\\" (禮) card hidden on the textbook shelf. The card''s reverse bears Ruggieri''s annotation: \\"Li 禮: humanitas. This is the cornerstone of communal coexistence.\\" You suddenly understand this 400-year-old missionary — he ingeniously linked the Confucian \\"Li\\" with the Western \\"humanitas,\\" seeing it as the foundation for civilizational dialogue."}', '{"zh-Hant":"為維護圖書館的秩序與對所有讀者的公平，請按照「禮」的精神，找出以下所有符合圖書館禮儀規範的正確行為：","zh-Hans":"为维护图书馆的秩序与对所有读者的公平，请按照「礼」的精神，找出以下所有符合图书馆礼仪规范的正确行为：","en":"To uphold library order and fairness to all readers, according to the spirit of ''Li'' (propriety), select ALL correct behaviors that comply with library etiquette:"}', '["a","b","c","d","e","f"]', 'RENYILIZX', '{"zh-Hant":"G/F G028·期刊與教科書室","zh-Hans":"G/F G028·期刊与教科书室","en":"G/F G028 · Textbooks"}', '{"zh-Hant":"認識教科書室使用規則，學習圖書館禮儀與版權規範","zh-Hans":"认识教科书室使用规则，学习图书馆礼仪与版权规范","en":"Learn textbook room rules, library etiquette, and copyright compliance"}', NULL, NULL, NULL, NULL),
  (11, '{"zh-Hant":"第十一關：知者寶鑒——智能終端的洞察力","zh-Hans":"第十一关：知者宝鉴——智能终端的洞察力","en":"Level 11: The Mirror of Knowledge — Insight Through Smart Devices"}', '{"zh-Hant":"你來到新書區，這裡代表著知識的流動與更新。羅明堅在手稿中曾寫道：「中國人之『知』，在於對新鮮事物的敏銳觀察，以及三省乎己的內心鑒察。」而今，這股力量已轉化為你手中的圖書館手機服務。","zh-Hans":"你来到新书区，这里代表著知识的流动与更新。罗明坚在手稿中曾写道：「中国人之『知』，在于对新鲜事物的敏锐观察，以及三省乎己的内心鉴察。」而今，这股力量已转化为你手中的图书馆手机服务。","en":"You arrive at the New Books Area, where knowledge flows and renews. Ruggieri once wrote in his manuscript: ''The Chinese concept of Zhi (知) lies in keen observation of the new and in reflective self-examination.'' Today, that power has transformed into the library''s mobile services in the palm of your hand."}', '{"zh-Hant":"掃碼成功後，手機螢幕上浮現出一行羅明堅的拉丁文轉寫：「ci 智：Prudentia。善用工具者，方能洞察未知。善用圖書館資源與服務，可以事半功倍。」你手中的「知」字卡牌開始發光，卡牌邊緣浮出最後一句指引：「信，是所有知識能否成立的最終保證。」","zh-Hans":"扫码成功后，手机萤幕上浮现出一行罗明坚的拉丁文转写：「ci 智：Prudentia。善用工具者，方能洞察未知。善用图书馆资源与服务，可以事半功倍。」你手中的「知」字卡牌开始发光，卡牌边缘浮出最后一句指引：「信，是所有知识能否成立的最终保证。」","en":"After a successful scan, a line of Ruggieri''s Latin transcription appears on your phone screen: \\"ci 智: Prudentia. Those who master their tools can perceive the unknown. Those who master library resources and services achieve twice the result with half the effort.\\" The \\"Zhi\\" card in your hand begins to glow, and its edge reveals one final directive: \\"Xin (信) — trust — is the ultimate guarantee that all knowledge can stand.\\""}', '{"zh-Hant":"圖書館已有許多服務可通過手機完成。關於圖書館手機借書，以下表述正確的是？","zh-Hans":"图书馆已有许多服务可通过手机完成。关于图书馆手机借书，以下表述正确的是？","en":"Many library services can now be done via mobile phone. Regarding mobile book borrowing, which statements are CORRECT?"}', '["a","b","d","e","f"]', 'UMAPPSCAN', '{"zh-Hant":"G/F 新書區","zh-Hans":"G/F 新书区","en":"G/F New Arrivals"}', '{"zh-Hant":"學習使用手機借書功能，掌握 UM App 圖書館服務","zh-Hans":"学习使用手机借书功能，掌握 UM App 图书馆服务","en":"Learn mobile book borrowing and master UM App library services"}', NULL, NULL, NULL, NULL),
  (12, '{"zh-Hant":"第十二關：真理之環——訊息萬變時代的終極誠信","zh-Hans":"第十二关：真理之环——讯息万变时代的终极诚信","en":"Level 12: The Circle of Truth — Ultimate Integrity in an Age of Ever-Changing Information"}', '{"zh-Hant":"你來到資訊素養室——這裡是學會分辨「真理」與「偽證」的地方。在 AI 橫行的年代，什麼才是真正可信的「信」？你將五張卡牌「仁、義、禮、知、信」按順序排列。卡牌背面的文字在燈下連成一段話：「福松影沒，非為金銀；九章再開，始於澳大。校訓之基，五德同輝。」你終於明白：鄭芝龍當年委託福松丸運送的，並非黃金珠寶，而是能改變中西文明對話走向的鑰匙。四百年前沉入西石的聖物，隨澳門大學的興建而重見天日，化作了這座學府的基石——「仁、義、禮、知、信」也從古老的手稿，化作了澳大人代代相傳的校訓。真正的寶藏，不在地底，而在這座圖書館的每一排書架、每一本書，以及你對真理的不懈追求之中。","zh-Hans":"你来到资讯素养室——这里是学会分辨「真理」与「伪证」的地方。在 AI 横行的年代，什么才是真正可信的「信」？你将五张卡牌「仁、义、礼、知、信」按顺序排列。卡牌背面的文字在灯下连成一段话：「福松影没，非为金银；九章再开，始于澳大。校训之基，五德同辉。」你终于明白：郑芝龙当年委托福松丸运送的，并非黄金珠宝，而是能改变中西文明对话走向的钥匙。四百年前沉入西石的圣物，随澳门大学的兴建而重见天日，化作了这座学府的基石——「仁、义、礼、知、信」也从古老的手稿，化作了澳大人代代相传的校训。真正的宝藏，不在地底，而在这座图书馆的每一排书架、每一本书，以及你对真理的不懈追求之中。","en":"You enter the Information Literacy Classroom — a place for learning to distinguish truth from false evidence. In this age of rampant AI, what truly deserves our ''trust''? You arrange the five cards — Ren, Yi, Li, Zhi, Xin — in order. The text on the reverse sides connects under the light: \\"Fushong vanished, not for gold or silver; Nine Chapters reopened, beginning at UM. The foundation of our motto, five virtues shining as one.\\" You finally understand: what Zheng Zhilong sent aboard the Fushong-maru was never gold and jewels, but keys that could change the course of civilizational dialogue between East and West. The sacred items that sank at Western Rock four centuries ago re-emerged with the building of the University of Macau, becoming the cornerstone of this institution — and ''Ren, Yi, Li, Zhi, Xin'' transformed from an ancient manuscript into the motto passed down through generations of UM students. The true treasure lies not underground, but in every bookshelf, every book, and in your unyielding pursuit of truth."}', '{"zh-Hant":"你將五張卡牌「仁、義、禮、知、信」按順序排列，拼合成一個完整的五角形。卡牌背面的文字在燈下連成一段話：「福松影沒，非為金銀；九章再開，始於澳大。校訓之基，五德同輝。」恭喜你，新生！你已掌握開啟這座智慧殿堂的鑰匙。新學期開始了，你的大學傳奇，才剛剛拉開序幕。","zh-Hans":"你将五张卡牌「仁、义、礼、知、信」按顺序排列，拼合成一个完整的五角形。卡牌背面的文字在灯下连成一段话：「福松影没，非为金银；九章再开，始于澳大。校训之基，五德同辉。」恭喜你，新生！你已掌握开启这座智慧殿堂的钥匙。新学期开始了，你的大学传奇，才刚刚拉开序幕。","en":"You arrange the five cards — Ren, Yi, Li, Zhi, Xin — in order, forming a complete pentagon. The text on their reverse sides connects under the light: \\"Fushong vanished, not for gold or silver; Nine Chapters reopened, beginning at UM. The foundation of our motto, five virtues shining as one.\\" Congratulations, freshman! You now hold the keys to this temple of wisdom. The new semester begins — and your university legend has only just begun."}', '{"zh-Hant":"AI 時代，圖書館發揮的作用愈加重要。以下關於 AI 和圖書館的表述，哪些是【錯誤】的？","zh-Hans":"AI 时代，图书馆发挥的作用愈加重要。以下关于 AI 和图书馆的表述，哪些是【错误】的？","en":"In the AI era, libraries play an increasingly vital role. Which of the following statements about AI and libraries are [FALSE]?"}', '["a","b","c"]', 'VERITASUM', '{"zh-Hant":"G/F 資訊素養室（G019）","zh-Hans":"G/F 资讯素养室（G019）","en":"G/F Information Literacy Room (G019)"}', '{"zh-Hant":"認識 AI 的局限性與學術誠信，學會批判性閱讀與規範引用","zh-Hans":"认识 AI 的局限性与学术诚信，学会批判性阅读与规范引用","en":"Understand AI limitations and academic integrity, learn critical reading and proper citation"}', '/video/finale-pentagon.mp4?v=20250710', NULL, NULL, NULL)
;

